mapper.insert:
insert into action_outbox (
    id, action_instance_id, topic, status, available_at, attempt_count, version, created_at, updated_at
) values (
    #{id}, #{actionInstanceId}, #{topic}, #{status}, #{availableAt}, #{attemptCount}, #{version}, #{createdAt}, #{updatedAt}
)

mapper.update:
update action_outbox
set topic = #{topic},
    status = #{status},
    available_at = #{availableAt},
    attempt_count = #{attemptCount},
    version = version + 1,
    updated_at = #{updatedAt}
where id = #{id}
  and version = #{version}
